function WhyMeCycler({ items }) {
  const [index, setIndex] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setIndex((i) => (i + 1) % items.length), 7500);
    return () => clearInterval(id);
  }, [items.length]);
  const item = items[index];
  return (
    <div className="bk-why-cycle">
      <div className="bk-why-cycle-item" key={index}>
        <span className="bk-why-cycle-icon">{item.icon}</span>
        <h4>{item.title}</h4>
        <p>{item.desc}</p>
      </div>
      <div className="bk-why-dots">
        {items.map((_, i) => (
          <span key={i} className={i === index ? "active" : ""} onClick={() => setIndex(i)} />
        ))}
      </div>
    </div>
  );
}

