function ProjectCarousel({ projects, onOpenImage }) {
  const trackRef = useRef(null);
  const [active, setActive] = useState(0);

  const scrollToIndex = (i) => {
    const track = trackRef.current;
    if (!track) return;
    const card = track.children[i];
    if (card) track.scrollTo({ left: card.offsetLeft - 4, behavior: "smooth" });
  };

  const go = (dir) => {
    const next = Math.max(0, Math.min(projects.length - 1, active + dir));
    setActive(next);
    scrollToIndex(next);
  };

  const onScroll = () => {
    const track = trackRef.current;
    if (!track) return;
    let closest = 0;
    let closestDist = Infinity;
    Array.from(track.children).forEach((card, i) => {
      const dist = Math.abs(card.offsetLeft - track.scrollLeft);
      if (dist < closestDist) {
        closestDist = dist;
        closest = i;
      }
    });
    setActive(closest);
  };

  return (
    <div className="bk-carousel">
      {projects.length > 1 && (
        <button
          className="bk-carousel-arrow prev"
          onClick={() => go(-1)}
          aria-label="Projet précédent"
          disabled={active === 0}
          type="button"
        >
          ‹
        </button>
      )}
      <div className="bk-carousel-track" ref={trackRef} onScroll={onScroll}>
        {projects.map((p) => {
          const Media = p.media;
          const hasImages = p.images && p.images.length > 0;
          return (
            <div className="bk-proj-card bk-carousel-card" key={p.title}>
              <div
                className={"bk-card-media" + (hasImages ? " has-images" : "")}
                onClick={hasImages ? () => onOpenImage(p.images, 0) : undefined}
              >
                <div className="bk-browser-bar">
                  <i /><i /><i />
                  <span className="bk-url">{p.url}</span>
                </div>
                {hasImages ? (
                  <>
                    <img src={p.images[0].src} alt={p.title} loading="lazy" />
                    <div className="bk-gallery-overlay">🔍 Voir les {p.images.length} captures</div>
                    <span className="bk-gallery-badge">🖼 {p.images.length}</span>
                  </>
                ) : (
                  <Media />
                )}
              </div>
              {hasImages && p.images.length > 1 && (
                <div className="bk-thumb-strip">
                  {p.images.map((img, i) => (
                    <button
                      key={i}
                      type="button"
                      className="bk-thumb-strip-item"
                      onClick={(e) => {
                        e.stopPropagation();
                        onOpenImage(p.images, i);
                      }}
                      title={img.caption || `Capture ${i + 1}`}
                    >
                      <img src={img.src} alt={img.caption || `${p.title} — capture ${i + 1}`} loading="lazy" />
                    </button>
                  ))}
                </div>
              )}
              <div className="bk-proj-body">
                <span className="bk-proj-label">{p.label}</span>
                <h3>{p.title}</h3>
                <p>{p.desc}</p>
                <div className="bk-tech-tags">
                  {p.tech.map((t) => (
                    <span key={t}>{t}</span>
                  ))}
                </div>
              </div>
            </div>
          );
        })}
      </div>
      {projects.length > 1 && (
        <button
          className="bk-carousel-arrow next"
          onClick={() => go(1)}
          aria-label="Projet suivant"
          disabled={active === projects.length - 1}
          type="button"
        >
          ›
        </button>
      )}
      {projects.length > 1 && (
        <div className="bk-carousel-dots">
          {projects.map((_, i) => (
            <span
              key={i}
              className={i === active ? "active" : ""}
              onClick={() => {
                setActive(i);
                scrollToIndex(i);
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
}

