function Reveal({ children, className = "", id }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            el.classList.add("in");
            const kids = el.querySelectorAll(".bk-exp-card, .bk-proj-card, .bk-t-item, .bk-method, .bk-cert-issuer");
            kids.forEach((k, i) => {
              k.style.animationDelay = i * 0.08 + "s";
            });
          }
        });
      },
      { threshold: 0.12 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return (
    <section id={id} className="bk-section">
      <div ref={ref} className={`bk-wrap bk-reveal bk-stagger ${className}`}>
        {children}
      </div>
    </section>
  );
}

function Stat({ count, label }) {
  const ref = useRef(null);
  const [value, setValue] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            let current = 0;
            const step = Math.max(1, Math.round(count / 30));
            const iv = setInterval(() => {
              current += step;
              if (current >= count) {
                current = count;
                clearInterval(iv);
              }
              setValue(current);
            }, 40);
            obs.unobserve(el);
          }
        });
      },
      { threshold: 0.5 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [count]);
  return (
    <div className="bk-stat" ref={ref}>
      <div className="bk-stat-num">{value}</div>
      <div className="bk-stat-label">{label}</div>
    </div>
  );
}

